import packageJson from '../package.json';
import { APIResponseError, AuthError } from './error';

// same as n8n
type LogLevel = 'silent' | 'error' | 'warn' | 'info' | 'debug' | 'verbose';
interface User {
	id: string;
}

export type SchemaType =
	| 'string'
	| 'number'
	| 'boolean'
	| 'bigint'
	| 'symbol'
	| 'array'
	| 'object'
	| 'function'
	| 'null'
	| 'undefined';

type Schema = { type: SchemaType; key?: string; value: string | Schema[]; path: string };

export namespace AiAssistantSDK {
	export interface ApplySuggestionResponse {
		sessionId: string;
		parameters: object;
	}

	export interface ChatRequestPayload {
		payload: object;
		sessionId?: string;
	}

	export interface ChatResponsePayload {
		sessionId?: string;
		messages: object[];
	}

	export interface AskAiRequestPayload {
		question: string;
		context: {
			schema: Array<{ nodeName: string; schema: Schema }>;
			inputSchema: { nodeName: string; schema: Schema };
			pushRef: string;
			ndvPushRef: string;
		};
		forNode: string;
	}

	export interface AskAiResponsePayload {
		code: string;
	}

	export interface AiCreditResponsePayload {
		apiKey: string;
		url: string;
	}

	export interface BuilderApiProxyTokenResponse {
		accessToken: string;
		tokenType: string;
	}
	export interface SandboxProxyConfigResponse {
		image: string;
	}

	export interface BuilderInstanceCreditsRequest {
		licenseCert: string;
	}

	export interface BuilderInstanceCreditsResponse {
		creditsQuota: number;
		creditsClaimed: number;
	}

	/**
	 * Token usage for one model. `output` includes reasoning tokens.
	 * Discriminated on `type` so the usage array can grow to cover non-LLM
	 * resources without changing this variant. Only `llmTokens` exists today.
	 */
	export type BuilderUsageItem = {
		type: 'llmTokens';
		model: string;
		uncachedInput: number;
		cacheRead: number;
		cacheWrite: number;
		output: number;
	};

	/**
	 * Instance AI credit pool. Shapes mirror the Builder pool — the AI service exposes an identical
	 * request/response contract under `/v1/instance-ai/*` — but it bills against a separate quota and
	 * Redis namespace at a per-account exchange rate.
	 */
	export interface InstanceAiApiProxyTokenResponse {
		accessToken: string;
		tokenType: string;
	}

	export interface InstanceAiClaimTokensRequest {
		dedupeId: string;
		usage: BuilderUsageItem[];
		/** Optional IA thread id, threaded into the claim telemetry on the service. */
		threadId?: string;
	}

	export interface InstanceAiClaimTokensResponse {
		delta: number;
		creditsClaimed: number;
		creditsQuota: number;
	}

	export interface InstanceAiCreditsResponse {
		creditsQuota: number;
		creditsClaimed: number;
		/**
		 * Whether the activation lock has been applied, forfeiting the rest of the quota
		 * (INS-1082). Optional: absent from a service that predates the lock.
		 */
		quotaLocked?: boolean;
	}

	export interface InstanceAiLockQuotaResponse {
		creditsQuota: number;
		creditsClaimed: number;
		quotaLocked: boolean;
	}
}

export { APIResponseError, AuthError } from './error';

const isObjectWithErrorMessage = (data: unknown): data is { message: string } => {
	return (
		typeof data === 'object' &&
		data !== null &&
		'message' in data &&
		typeof data?.message === 'string'
	);
};

const isObjectWithNestedErrorMessage = (data: unknown): data is { error: { message: string } } => {
	return (
		typeof data === 'object' &&
		data !== null &&
		'error' in data &&
		isObjectWithErrorMessage((data as { error: unknown }).error)
	);
};

/**
 * Extract a human-readable error message from an API error response body,
 * handling both NestJS exceptions (`{ message }`) and the OpenAI-style error
 * objects (`{ error: { message } }`) returned by the ai-credits endpoint.
 */
const extractApiErrorMessage = (data: unknown, fallback: string): string => {
	if (isObjectWithNestedErrorMessage(data)) {
		return data.error.message;
	}
	if (isObjectWithErrorMessage(data)) {
		return data.message;
	}
	return fallback;
};

/**
 * Extract both the human-readable message and the machine-readable code from an API
 * error body. The message handles NestJS (`{ message }`) and nested
 * (`{ error: { message } }`) shapes; the code prefers a top-level `code` (the current
 * contract, e.g. `{ ...nestJsBody, code: 'quota_exhausted' }`) and falls back to a
 * nested `error.type`. `code` is undefined for untagged errors.
 */
const extractApiError = (data: unknown, fallback: string): { message: string; code?: string } => {
	const message = extractApiErrorMessage(data, fallback);
	if (typeof data !== 'object' || data === null) {
		return { message };
	}
	const record = data as Record<string, unknown>;
	const nestedType =
		typeof record.error === 'object' && record.error !== null
			? (record.error as Record<string, unknown>).type
			: undefined;
	const code =
		typeof record.code === 'string'
			? record.code
			: typeof nestedType === 'string'
				? nestedType
				: undefined;
	return { message, code };
};

const DEFAULT_SERVICE_BASE_URL = 'https://ai-assistant.n8n.io';

export class AiAssistantClient {
	private licenseCert: string;
	private consumerId: string;
	private n8nVersion: string;
	private instanceId: string;
	private baseUrl = DEFAULT_SERVICE_BASE_URL;
	private logLevel = 'info';
	private activeToken: string | undefined;

	/**
	 * Create a client for the AI service.
	 * @param licenseCert - The license certificate. You can get it from the n8n.
	 * @param consumerId - The consumer ID.
	 * @param n8nVersion - The n8n version.
	 * @param instanceId - The n8n instance ID.
	 * @param baseUrl - The base URL of the AI service API.
	 * @returns {RequestHandler}
	 */
	constructor({
		licenseCert,
		consumerId,
		n8nVersion,
		instanceId,
		baseUrl,
		logLevel,
	}: {
		licenseCert: string;
		consumerId: string;
		n8nVersion: string;
		instanceId: string;
		baseUrl?: string;
		logLevel?: LogLevel;
	}) {
		this.licenseCert = licenseCert;
		this.consumerId = consumerId;
		this.n8nVersion = n8nVersion;
		this.instanceId = instanceId;
		this.baseUrl = baseUrl ?? this.baseUrl;
		this.logLevel = logLevel ?? this.logLevel;

		this.debug('Initializing AI Assistant Service Client', {
			baseUrl: this.baseUrl,
			consumerId: this.consumerId,
			n8nVersion: this.n8nVersion,
			licenseCert: this.licenseCert.substring(0, 5),
		});
	}

	async chat(payload: AiAssistantSDK.ChatRequestPayload, user: User): Promise<Response> {
		return await this.postRequest('/v1/chat', payload, user);
	}

	async applySuggestion(
		payload: {
			sessionId: string;
			suggestionId: string;
		},
		user: User,
	): Promise<AiAssistantSDK.ApplySuggestionResponse> {
		const response = await this.postRequest('/v1/chat/apply-suggestion', payload, user);

		const data = await response.json();
		if (isValidApplySuggestionResponse(data)) {
			return data;
		}

		throw new APIResponseError('Invalid response from assistant service');
	}

	async askAi(
		payload: AiAssistantSDK.AskAiRequestPayload,
		user: User,
	): Promise<AiAssistantSDK.AskAiResponsePayload> {
		{
			const response = await this.postRequest('/v1/ask-ai', payload, user);

			const data = await response.json();

			if (isValidAskAiResponse(data)) {
				return data;
			}

			throw new APIResponseError('Invalid response from assistant service');
		}
	}

	async generateAiCreditsCredentials(user: User): Promise<AiAssistantSDK.AiCreditResponsePayload> {
		{
			const url = `${this.baseUrl}/v1/ai-credits/credentials`;

			try {
				const response = await fetch(url, {
					headers: this.getHeaders(user),
					method: 'POST',
					body: JSON.stringify({
						licenseCert: this.licenseCert,
					}),
				});

				if (!response.ok) {
					const errorData = await response.json().catch(() => null);
					const errorMessage = extractApiErrorMessage(
						errorData,
						`Failed to generate AI credits credentials: ${response.statusText}`,
					);
					throw new APIResponseError(errorMessage, response.status);
				}

				const data = await response.json();

				if (isValidAiCreditsResponse(data)) {
					return data;
				}

				throw new APIResponseError('Invalid response from assistant service');
			} catch (error) {
				if (error instanceof APIResponseError) {
					throw error;
				}
				if (isObjectWithErrorMessage(error)) {
					throw new APIResponseError(error.message);
				} else {
					throw new APIResponseError('unknown error');
				}
			}
		}
	}

	getApiProxyBaseUrl(): string {
		return this.baseUrl + '/v1/api-proxy';
	}

	getSandboxProxyBaseUrl(): string {
		return this.baseUrl + '/v1/sandbox-proxy';
	}

	async getSandboxProxyConfig(): Promise<AiAssistantSDK.SandboxProxyConfigResponse> {
		const url = `${this.baseUrl}/v1/sandbox-proxy/config`;

		try {
			const response = await fetch(url);

			if (!response.ok) {
				const errorData = await response.json().catch(() => null);
				const errorMessage = isObjectWithErrorMessage(errorData)
					? errorData.message
					: `Failed to get sandbox proxy config: ${response.statusText}`;
				throw new APIResponseError(errorMessage, response.status);
			}

			const data = await response.json();

			if (typeof data === 'object' && data && 'image' in data && typeof data.image === 'string') {
				return data as AiAssistantSDK.SandboxProxyConfigResponse;
			}

			throw new APIResponseError('Invalid response from sandbox proxy config endpoint');
		} catch (error) {
			if (error instanceof APIResponseError) {
				throw error;
			}
			if (isObjectWithErrorMessage(error)) {
				throw new APIResponseError(error.message);
			}
			throw new APIResponseError('unknown error');
		}
	}

	/**
	 * Update the license certificate and clear the active token.
	 * This should be called when the license is renewed or changed.
	 * @param licenseCert - The new license certificate.
	 */
	updateLicenseCert(licenseCert: string): void {
		this.licenseCert = licenseCert;
		this.activeToken = undefined;
	}

	async getBuilderApiProxyToken(
		user: User,
		options?: { userMessageId?: string },
	): Promise<AiAssistantSDK.BuilderApiProxyTokenResponse> {
		const url = `${this.baseUrl}/v1/builder/api-proxy-token`;

		return await this.request(
			url,
			{
				headers: this.getHeaders(user),
				method: 'POST',
				body: JSON.stringify({
					licenseCert: this.licenseCert,
					userMessageId: options?.userMessageId,
				}),
			},
			isValidBuilderApiProxyTokenResponse,
			'Failed to get builder API proxy token',
		);
	}

	async markBuilderSuccess(
		user: User,
		headers: { Authorization: string },
	): Promise<{ creditsQuota: number; creditsClaimed: number }> {
		const url = `${this.baseUrl}/v1/builder/success`;

		return await this.request(
			url,
			{
				headers: {
					...this.getHeaders(user),
					'x-authorization': headers.Authorization,
				},
				body: JSON.stringify({
					licenseCert: this.licenseCert,
				}),
				method: 'POST',
			},
			isValidBuilderInstanceCreditsResponse,
			'Failed to mark builder success',
		);
	}

	async getBuilderInstanceCredits(
		user: User,
	): Promise<AiAssistantSDK.BuilderInstanceCreditsResponse> {
		const url = `${this.baseUrl}/v1/builder/usage`;

		return await this.request(
			url,
			{
				headers: this.getHeaders(user),
				method: 'POST',
				body: JSON.stringify({
					licenseCert: this.licenseCert,
				}),
			},
			isValidBuilderInstanceCreditsResponse,
			'Failed to get builder usage',
		);
	}

	/**
	 * Request an api-proxy token for the Instance AI credit pool. Mirrors
	 * {@link getBuilderApiProxyToken} but the issued token bills against the IA pool.
	 */
	async getInstanceAiApiProxyToken(
		user: User,
		options?: { userMessageId?: string },
	): Promise<AiAssistantSDK.InstanceAiApiProxyTokenResponse> {
		const url = `${this.baseUrl}/v1/instance-ai/api-proxy-token`;

		return await this.request(
			url,
			{
				headers: this.getHeaders(user),
				method: 'POST',
				body: JSON.stringify({
					licenseCert: this.licenseCert,
					userMessageId: options?.userMessageId,
				}),
			},
			isValidInstanceAiApiProxyTokenResponse,
			'Failed to get instance AI API proxy token',
		);
	}

	/**
	 * Claim decimal credits for Instance AI token usage from a completed/stopped/errored run.
	 * Idempotent per `dedupeId` (the service dedupes replays).
	 */
	async markInstanceAiTokenUsage(
		user: User,
		headers: { Authorization: string },
		payload: AiAssistantSDK.InstanceAiClaimTokensRequest,
	): Promise<AiAssistantSDK.InstanceAiClaimTokensResponse> {
		const url = `${this.baseUrl}/v1/instance-ai/claim-tokens`;

		return await this.request(
			url,
			{
				headers: {
					...this.getHeaders(user),
					'x-authorization': headers.Authorization,
				},
				body: JSON.stringify({
					licenseCert: this.licenseCert,
					dedupeId: payload.dedupeId,
					usage: payload.usage,
					threadId: payload.threadId,
				}),
				method: 'POST',
			},
			isValidInstanceAiClaimTokensResponse,
			'Failed to claim instance AI token usage',
		);
	}

	async getInstanceAiCredits(user: User): Promise<AiAssistantSDK.InstanceAiCreditsResponse> {
		const url = `${this.baseUrl}/v1/instance-ai/usage`;

		return await this.request(
			url,
			{
				headers: this.getHeaders(user),
				method: 'POST',
				body: JSON.stringify({
					licenseCert: this.licenseCert,
				}),
			},
			isValidInstanceAiCreditsResponse,
			'Failed to get instance AI usage',
		);
	}

	/**
	 * Forfeit the remaining Instance AI quota because the instance has activated (INS-1082).
	 * What counts as "activated" is decided by the caller; the service only applies the outcome,
	 * and refuses it outside a trial plan. Idempotent, so this can be re-asserted freely.
	 */
	async lockInstanceAiQuota(
		user: User,
		options: { activatedAt?: number } = {},
	): Promise<AiAssistantSDK.InstanceAiLockQuotaResponse> {
		const url = `${this.baseUrl}/v1/instance-ai/lock-quota`;

		return await this.request(
			url,
			{
				headers: this.getHeaders(user),
				method: 'POST',
				body: JSON.stringify({
					licenseCert: this.licenseCert,
					...(options.activatedAt !== undefined ? { activatedAt: options.activatedAt } : {}),
				}),
			},
			isValidInstanceAiLockQuotaResponse,
			'Failed to lock instance AI quota',
		);
	}

	private getHeadersWithAuthToken(user: User) {
		return {
			authorization: `Bearer ${this.activeToken}`,
			...this.getHeaders(user),
		};
	}

	private getHeaders(user: User) {
		return {
			'Content-Type': 'application/json',
			'x-consumer-id': this.consumerId,
			'x-user-id': user.id,
			'x-sdk-version': packageJson.version,
			'x-n8n-version': this.n8nVersion,
			'x-instance-id': this.instanceId,
		};
	}

	/**
	 * Shared fetch + error handling for JSON endpoints: throws APIResponseError on a non-ok
	 * status (using the body's `message` when present, else `${errorPrefix}: ${statusText}`)
	 * or when the parsed body fails `isValid`, and normalizes thrown errors to APIResponseError.
	 */
	private async request<T>(
		url: string,
		init: RequestInit,
		isValid: (data: unknown) => data is T,
		errorPrefix: string,
	): Promise<T> {
		try {
			const response = await fetch(url, init);

			if (!response.ok) {
				const errorData = await response.json();
				const { message, code } = extractApiError(
					errorData,
					`${errorPrefix}: ${response.statusText}`,
				);
				throw new APIResponseError(message, response.status, code);
			}

			const data: unknown = await response.json();
			if (!isValid(data)) {
				throw new APIResponseError('Invalid response from assistant service');
			}
			return data;
		} catch (error) {
			if (error instanceof APIResponseError) {
				throw error;
			}
			if (isObjectWithErrorMessage(error)) {
				throw new APIResponseError(error.message);
			}
			throw new APIResponseError('unknown error');
		}
	}

	private async refreshAuthToken(): Promise<void> {
		const response = await fetch(`${this.baseUrl}/auth/token`, {
			method: 'POST',
			body: JSON.stringify({ licenseCert: this.licenseCert }),
			headers: { 'Content-Type': 'application/json' },
		});

		const data = await response.json().catch(() => null);
		if (
			typeof data === 'object' &&
			data &&
			'accessToken' in data &&
			data.accessToken &&
			typeof data.accessToken === 'string'
		) {
			this.activeToken = data.accessToken;
			return;
		}

		const errorMessage = isObjectWithErrorMessage(data) ? data.message : 'Unknown error';

		throw new AuthError(`Could not retrieve access token: ${errorMessage}`);
	}

	private async postRequest(endpoint: string, payload: object, user: User): Promise<Response> {
		if (!this.activeToken) {
			await this.refreshAuthToken();
		}

		if (!this.activeToken) {
			throw new AuthError('No token to call assistant service');
		}

		const url = `${this.baseUrl}${endpoint}`;
		let response = await fetch(url, {
			headers: this.getHeadersWithAuthToken(user),
			method: 'POST',
			body: JSON.stringify(payload),
		});

		// retry if unauthorized (token is expired)
		if (!response.ok && response.status === 401) {
			await this.refreshAuthToken();

			response = await fetch(url, {
				headers: this.getHeadersWithAuthToken(user),
				method: 'POST',
				body: JSON.stringify(payload),
			});
		}

		if (!response.ok) {
			const error = await response.json().catch(() => null);
			this.debug(`API Error ${JSON.stringify(error)}`);
			const message = isObjectWithErrorMessage(error) ? error.message : response.statusText;
			throw new APIResponseError(message, response.status);
		}

		return response;
	}

	private debug(message: string, debugInfo?: Record<string, string | number>) {
		if (this.logLevel === 'debug') {
			console.debug(formatLog(message), formatLog(JSON.stringify(debugInfo)));
		}
	}
}

function formatLog(message: string) {
	return `[ai-assistant-sdk] ${message}`;
}

function isValidApplySuggestionResponse(
	response: unknown,
): response is AiAssistantSDK.ApplySuggestionResponse {
	return (
		typeof response === 'object' &&
		!!response &&
		'parameters' in response &&
		'sessionId' in response
	);
}

function isValidAskAiResponse(response: unknown): response is AiAssistantSDK.AskAiResponsePayload {
	return typeof response === 'object' && !!response && 'code' in response;
}

function isValidAiCreditsResponse(
	response: unknown,
): response is AiAssistantSDK.AiCreditResponsePayload {
	return typeof response === 'object' && !!response && 'apiKey' in response && 'url' in response;
}

function isValidBuilderApiProxyTokenResponse(
	response: unknown,
): response is AiAssistantSDK.BuilderApiProxyTokenResponse {
	return (
		typeof response === 'object' &&
		!!response &&
		'accessToken' in response &&
		'tokenType' in response &&
		typeof response.accessToken === 'string' &&
		typeof response.tokenType === 'string'
	);
}

function isValidBuilderInstanceCreditsResponse(
	response: unknown,
): response is AiAssistantSDK.BuilderInstanceCreditsResponse {
	return (
		typeof response === 'object' &&
		!!response &&
		'creditsQuota' in response &&
		'creditsClaimed' in response &&
		typeof response.creditsQuota === 'number' &&
		typeof response.creditsClaimed === 'number'
	);
}

function isValidInstanceAiApiProxyTokenResponse(
	response: unknown,
): response is AiAssistantSDK.InstanceAiApiProxyTokenResponse {
	return (
		typeof response === 'object' &&
		!!response &&
		'accessToken' in response &&
		'tokenType' in response &&
		typeof response.accessToken === 'string' &&
		typeof response.tokenType === 'string'
	);
}

function isValidInstanceAiClaimTokensResponse(
	response: unknown,
): response is AiAssistantSDK.InstanceAiClaimTokensResponse {
	return (
		typeof response === 'object' &&
		!!response &&
		'delta' in response &&
		'creditsClaimed' in response &&
		'creditsQuota' in response &&
		typeof response.delta === 'number' &&
		typeof response.creditsClaimed === 'number' &&
		typeof response.creditsQuota === 'number'
	);
}

function isValidInstanceAiCreditsResponse(
	response: unknown,
): response is AiAssistantSDK.InstanceAiCreditsResponse {
	return (
		typeof response === 'object' &&
		!!response &&
		'creditsQuota' in response &&
		'creditsClaimed' in response &&
		typeof response.creditsQuota === 'number' &&
		typeof response.creditsClaimed === 'number' &&
		// Accept-if-absent: a service predating the activation lock omits it entirely.
		(!('quotaLocked' in response) || typeof response.quotaLocked === 'boolean')
	);
}

function isValidInstanceAiLockQuotaResponse(
	response: unknown,
): response is AiAssistantSDK.InstanceAiLockQuotaResponse {
	return (
		typeof response === 'object' &&
		!!response &&
		'creditsQuota' in response &&
		'creditsClaimed' in response &&
		'quotaLocked' in response &&
		typeof response.creditsQuota === 'number' &&
		typeof response.creditsClaimed === 'number' &&
		typeof response.quotaLocked === 'boolean'
	);
}
